package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.section.clazz.Parameter;
import net.officefloor.plugin.variable.Out;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.escalation.NotFoundException;
import org.springframework.samples.petclinic.rest.function.common.Lookups;

/**
 * Replay step of {@code POST /api/owners}: loads the owner originally created under a repeated
 * {@code Idempotency-Key} (its id arriving from {@link CheckIdempotencyKey}) so {@link
 * RespondWithOwner} can return it with 200.
 */
public class LoadStoredOwner {

    public void service(@Parameter Integer ownerId, OwnerRepository ownerRepository, Out<Owner> loaded)
            throws NotFoundException {
        loaded.set(Lookups.findOrNotFound(() -> ownerRepository.findById(ownerId),
                "Owner not found: " + ownerId));
    }
}
==== ValidateNewOwner ====
package org.springframework.samples.petclinic.rest.function.owner;

import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;

import net.officefloor.plugin.variable.Out;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.DisposableEmailDomainException;
import org.springframework.samples.petclinic.rest.escalation.FutureRegistrationDateException;
import org.springframework.samples.petclinic.rest.escalation.InvalidEmailException;
import org.springframework.samples.petclinic.rest.escalation.InvalidPostcodeException;
import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;
import org.springframework.samples.petclinic.rest.escalation.MissingOwnerFieldsException;
import org.springframework.web.bind.annotation.RequestBody;

/**
 * First step of {@code POST /api/owners}. Normalizes the address to its canonical form (see
 * {@link OwnerAddress}) and stores it back on the request, then rejects a request that is missing
 * or blank in any required field (firstName, lastName, address, city, telephone) — the address
 * being tested for blankness after normalization — with a 400 whose body lists the offending field
 * names. Then normalizes the telephone to E.164 form (see {@link
 * TelephoneE164}), storing the E.164 value back on the request so later steps persist and return
 * it; a telephone that cannot form valid E.164 is rejected with a 400. Finally, when a {@code
 * postcode} is supplied it is validated against the city's region (see {@link Postcode}); a
 * malformed or out-of-range postcode is rejected with a 400, while an absent postcode is accepted.
 * A supplied {@code registrationDate} later than the server date is rejected with a 400, while an
 * absent registration date (defaulted later to the server date) is accepted. Runs before
 * {@link BuildOwner} maps the body to an {@link
 * org.springframework.samples.petclinic.model.Owner}.
 */
public class ValidateNewOwner {

    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> validated)
            throws MissingOwnerFieldsException, InvalidTelephoneException, InvalidEmailException,
            InvalidPostcodeException, FutureRegistrationDateException, DisposableEmailDomainException {
        // Address may arrive structured (addressLine1 [+ addressLine2]) or as the flat 'address'.
        // The structured form is preferred whenever addressLine1 is non-blank; otherwise the flat
        // value is used (backward-compatible). Whichever fields are supplied are normalized, and the
        // flat 'address' everything downstream reads is composed from the structured fields when they
        // win: normalized addressLine1 plus, when addressLine2 is present, a space and normalized
        // addressLine2.
        String addressLine1 = OwnerAddress.normalize(request.getAddressLine1());
        if (!addressLine1.isEmpty()) {
            String addressLine2 = OwnerAddress.normalize(request.getAddressLine2());
            request.setAddressLine1(addressLine1);
            request.setAddressLine2(addressLine2.isEmpty() ? null : addressLine2);
            request.setAddress(addressLine2.isEmpty() ? addressLine1 : addressLine1 + " " + addressLine2);
        }
        else {
            request.setAddress(OwnerAddress.normalize(request.getAddress()));
        }
        List<String> missing = new ArrayList<>();
        if (isBlank(request.getFirstName())) {
            missing.add("firstName");
        }
        if (isBlank(request.getLastName())) {
            missing.add("lastName");
        }
        if (isBlank(request.getAddress())) {
            missing.add("address");
        }
        if (isBlank(request.getCity())) {
            missing.add("city");
        }
        if (isBlank(request.getTelephone())) {
            missing.add("telephone");
        }
        if (!missing.isEmpty()) {
            throw new MissingOwnerFieldsException(missing);
        }
        request.setTelephone(TelephoneE164.normalize(request.getTelephone()));
        request.setEmail(OwnerEmail.normalize(request.getEmail()));
        // Postcode is optional; when present it must be a 4-digit code valid for the city's region.
        Postcode.validate(request.getPostcode(), request.getCity());
        // Registration date is optional; when supplied it may be back-dated but never into the future.
        LocalDate registrationDate = request.getRegistrationDate();
        if (registrationDate != null && registrationDate.isAfter(LocalDate.now())) {
            throw new FutureRegistrationDateException(registrationDate);
        }
        validated.set(request);
    }

    private static boolean isBlank(String value) {
        return value == null || value.isBlank();
    }
}
==== CheckOwnerIdentityUnique ====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.DuplicateOwnerIdentityException;

/**
 * The duplicate-detection step of {@code POST /api/owners}. Duplicate detection is the single
 * {@code identityKey} (see {@link OwnerIdentityKey}): a request is a duplicate only when an existing
 * owner carries the <em>same whole key</em> — normalized telephone, email and {@code soundex(lastName)}
 * all equal. There is no separate household-duplicate block: the postcode is not part of the key, so
 * two owners with the same last name and postcode but different telephones have different keys and are
 * both allowed (the weaker overlap is a soft match, see {@link AssignPossibleDuplicate}); only a
 * genuine re-submission of the same owner is rejected with 409.
 *
 * <p>The email-domain blocklist is applied earlier, in {@link ValidateNewOwner}, so a disposable
 * domain is a 400 before this step runs. Soft-deleted owners are ignored here.
 *
 * <p>The {@code sharesHousehold} hint bypasses this block: a request that declares itself a member
 * of a shared household is allowed through and created as a legitimate second member (and is not
 * flagged as a possible duplicate, see {@link AssignPossibleDuplicate}).
 *
 * <p>Runs after {@link ValidateNewOwner} has normalized the request and before {@link BuildOwner},
 * so a duplicate is a 409 rather than a persisted record.
 */
public class CheckOwnerIdentityUnique {

    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
            throws DuplicateOwnerIdentityException {
        if (Household.sharesHousehold(request)) {
            return; // declared household member: bypass the duplicate block
        }
        String identityKey = OwnerIdentityKey.forRequest(request);
        for (Owner owner : ownerRepository.findAll()) {
            if (owner.isDeleted()) {
                continue; // a soft-deleted owner no longer blocks a new create
            }
            if (identityKey.equals(OwnerIdentityKey.forOwner(owner))) {
                throw new DuplicateOwnerIdentityException(Household.idFor(request));
            }
        }
    }
}
==== CheckOwnerCityCapacity ====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.OwnerCityFullException;

/**
 * Rejects a create-owner request whose city is already at capacity: a city that already contains
 * 50 or more owners cannot take another. The city is compared case-insensitively. Runs after
 * {@link ValidateNewOwner} has
 * published the request, and before {@link BuildOwner}, so a full city is a 409 rather than a
 * persisted record.
 */
public class CheckOwnerCityCapacity {

    /** Maximum number of owners permitted in a single city. */
    private static final long CITY_CAPACITY = 50;

    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
            throws OwnerCityFullException {
        String city = request.getCity();
        long inCity = ownerRepository.findAll().stream()
                .filter(existing -> city != null && city.equalsIgnoreCase(existing.getCity()))
                .count();
        if (inCity >= CITY_CAPACITY) {
            throw new OwnerCityFullException(city);
        }
    }
}
==== CheckOwnerDailyLimit ====
package org.springframework.samples.petclinic.rest.function.owner;

import java.time.LocalDate;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.DailyOwnerLimitException;

/**
 * Rejects a create-owner request once a business day's creation quota is exhausted: if 100 or more
 * owners already carry the {@code registrationDate} this owner would receive, no further owner may
 * be created for that day. The counted day is the effective registration date (supplied on the
 * request or defaulted to the server date) rolled forward onto a business day, matching how
 * {@link BuildOwner} stamps the new owner via {@link BusinessDay#rollForward(LocalDate)}, so the
 * owners this rule counts are exactly those sharing the resulting day. Runs after
 * {@link ValidateNewOwner} has published the request, and before {@link BuildOwner}, so a full day
 * is a 429 rather than a persisted record.
 */
public class CheckOwnerDailyLimit {

    /** Maximum number of owners that may be created in a single day. */
    private static final long DAILY_LIMIT = 100;

    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
            throws DailyOwnerLimitException {
        LocalDate effective = request.getRegistrationDate();
        if (effective == null) {
            effective = LocalDate.now();
        }
        // Count owners against the same adjusted business day BuildOwner will stamp on this owner,
        // so a weekend create is bucketed with the Monday it rolls forward to.
        LocalDate businessDay = BusinessDay.rollForward(effective);
        long createdThatDay = ownerRepository.findAll().stream()
                .filter(existing -> businessDay.equals(existing.getRegistrationDate()))
                .count();
        if (createdThatDay >= DAILY_LIMIT) {
            throw new DailyOwnerLimitException(createdThatDay);
        }
    }
}
==== BuildOwner ====
package org.springframework.samples.petclinic.rest.function.owner;

import java.time.LocalDate;

import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.mapper.OwnerMapper;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;

public class BuildOwner {

    public void service(@Val OwnerFieldsDto request, OwnerMapper ownerMapper, Out<Owner> built) {
        Owner owner = ownerMapper.toOwner(request);
        LocalDate effective = owner.getRegistrationDate();
        if (effective == null) {
            effective = LocalDate.now();
        }
        // Registration must fall on a business day: a supplied or defaulted weekend date rolls
        // forward to the next Monday, and later steps derive their values from the adjusted date.
        owner.setRegistrationDate(BusinessDay.rollForward(effective));
        built.set(owner);
    }
}
==== AssignMemberId ====
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.HashSet;
import java.util.Set;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.util.CheckDigit;
import org.springframework.samples.petclinic.util.FiscalYear;
import org.springframework.samples.petclinic.util.IdentityVersion;
import org.springframework.samples.petclinic.util.LocalityResolver;
import org.springframework.samples.petclinic.util.Sha256Hash;

/**
 * Assigns the owner's {@code memberId} before it is saved. It unifies the former
 * {@code customerCode} and {@code membershipNumber} into a single value formatted
 * {@code <REGION><FY><HASH8><CHK>}, where:
 *
 * <ul>
 * <li>{@code REGION} is the version-2 region code: the region derived from the postcode (see
 * {@link LocalityResolver}) with the fixed {@link IdentityVersion#TAG} mixed in, so it never equals
 * a version-1 region and the plain {@code locality} is no longer read back off it;</li>
 * <li>{@code FY} is the last two digits of the fiscal year (starting 1 July) of the
 * business-day-adjusted {@code registrationDate}, zero-padded;</li>
 * <li>{@code HASH8} is the first 8 upper-case hex characters of SHA-256 over the concatenation of
 * the normalized telephone and the last name (the same HASH8 used by the region-and-hash identity);
 * and</li>
 * <li>{@code CHK} is a single Luhn check digit computed over the digits of
 * {@code <REGION><FY><HASH8>} (see {@link CheckDigit}).</li>
 * </ul>
 *
 * (e.g. {@code NSW273F1A9C2B4}.) The telephone was normalized to E.164 by {@link ValidateNewOwner},
 * so {@code owner.getTelephone()} is already the normalized value, and {@link BuildOwner} has set the
 * business-day-adjusted {@code registrationDate}.
 *
 * <p>Should the computed id collide with an existing owner's {@code memberId}, it is de-duplicated by
 * appending {@code -<n>} with the smallest {@code n} of 2 or more that makes it unique
 * (e.g. {@code NSW273F1A9C2B4-2}). Runs after {@link BuildOwner} and before {@link SaveOwner}, so
 * {@link OwnerRepository#findAll()} returns only the pre-existing owners. Mutates the entity in place
 * so {@link SaveOwner} persists it.
 */
public class AssignMemberId {

    /** Number of upper-case hex characters taken from the SHA-256 digest. */
    private static final int HASH_LENGTH = 8;

    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
        String region = LocalityResolver.localityOf(owner.getPostcode(), owner.getCity())
                + IdentityVersion.TAG;
        String fy = String.format("%02d", FiscalYear.yearOf(owner.getRegistrationDate()) % 100);
        String hash8 = Sha256Hash.upperHex(owner.getTelephone() + owner.getLastName(), HASH_LENGTH);
        String body = region + fy + hash8;
        String baseId = body + CheckDigit.luhnOf(body);

        Set<String> existingIds = new HashSet<>();
        for (Owner other : ownerRepository.findAll()) {
            existingIds.add(other.getMemberId());
        }

        String memberId = baseId;
        for (int n = 2; existingIds.contains(memberId); n++) {
            memberId = baseId + "-" + n;
        }
        owner.setMemberId(memberId);
    }
}
