8	/**
9	 * First step of {@code POST /api/owners}. Reads the optional {@code Idempotency-Key} header and, if
10	 * a create has already been made under that key, replays the originally created owner (a 200 via
11	 * {@link LoadStoredOwner} + {@link RespondWithOwner}) instead of creating a duplicate. Otherwise it
12	 * proceeds with the normal create pipeline (starting at {@link ValidateNewOwner}), publishing the
13	 * key so {@link RecordIdempotencyKey} can remember the owner that create produces.
14	 *
15	 * <p>The key is published even when absent (as an empty {@link IdempotencyKey}) so the recording
16	 * step always has a value to read; recording is skipped when no key was supplied.
17	 */
18	public class CheckIdempotencyKey {
19	
20	    @FunctionalInterface
21	    public interface Replay {
22	        void replay(Integer ownerId);
23	    }
24	
25	    @FunctionalInterface
26	    public interface Proceed {
27	        void proceed();
28	    }
29	
30	    public void service(@HttpHeaderParameter("Idempotency-Key") String key, IdempotencyStore store,
31	            Out<IdempotencyKey> keyOut, @Flow("replay") Replay replay, @Flow("proceed") Proceed proceed) {
32	        keyOut.set(new IdempotencyKey(key));
33	        if (key != null && !key.isBlank()) {
34	            Integer existingOwnerId = store.find(key);
35	            if (existingOwnerId != null) {
36	                replay.replay(existingOwnerId); // repeat of a seen key: return the original owner (200)
37	                return;
38	            }
39	        }
40	        proceed.proceed(); // new (or keyless) request: run the normal create pipeline
41	    }
42	}
