67	package org.springframework.samples.petclinic.rest.function.owner;
68	
69	import java.time.LocalDate;
70	import java.util.ArrayList;
71	import java.util.List;
72	
73	import net.officefloor.plugin.variable.Out;
74	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
75	import org.springframework.samples.petclinic.rest.escalation.DisposableEmailDomainException;
76	import org.springframework.samples.petclinic.rest.escalation.FutureRegistrationDateException;
77	import org.springframework.samples.petclinic.rest.escalation.InvalidEmailException;
78	import org.springframework.samples.petclinic.rest.escalation.InvalidPostcodeException;
79	import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;
80	import org.springframework.samples.petclinic.rest.escalation.MissingOwnerFieldsException;
81	import org.springframework.web.bind.annotation.RequestBody;
82	
83	/**
84	 * First step of {@code POST /api/owners}. Normalizes the address to its canonical form (see
85	 * {@link OwnerAddress}) and stores it back on the request, then rejects a request that is missing
86	 * or blank in any required field (firstName, lastName, address, city, telephone) — the address
87	 * being tested for blankness after normalization — with a 400 whose body lists the offending field
88	 * names. Then normalizes the telephone to E.164 form (see {@link
89	 * TelephoneE164}), storing the E.164 value back on the request so later steps persist and return
90	 * it; a telephone that cannot form valid E.164 is rejected with a 400. Finally, when a {@code
91	 * postcode} is supplied it is validated against the city's region (see {@link Postcode}); a
92	 * malformed or out-of-range postcode is rejected with a 400, while an absent postcode is accepted.
93	 * A supplied {@code registrationDate} later than the server date is rejected with a 400, while an
94	 * absent registration date (defaulted later to the server date) is accepted. Runs before
95	 * {@link BuildOwner} maps the body to an {@link
96	 * org.springframework.samples.petclinic.model.Owner}.
97	 */
98	public class ValidateNewOwner {
99	
100	    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> validated)
101	            throws MissingOwnerFieldsException, InvalidTelephoneException, InvalidEmailException,
102	            InvalidPostcodeException, FutureRegistrationDateException, DisposableEmailDomainException {
103	        // Address may arrive structured (addressLine1 [+ addressLine2]) or as the flat 'address'.
104	        // The structured form is preferred whenever addressLine1 is non-blank; otherwise the flat
105	        // value is used (backward-compatible). Whichever fields are supplied are normalized, and the
106	        // flat 'address' everything downstream reads is composed from the structured fields when they
107	        // win: normalized addressLine1 plus, when addressLine2 is present, a space and normalized
108	        // addressLine2.
109	        String addressLine1 = OwnerAddress.normalize(request.getAddressLine1());
110	        if (!addressLine1.isEmpty()) {
111	            String addressLine2 = OwnerAddress.normalize(request.getAddressLine2());
112	            request.setAddressLine1(addressLine1);
113	            request.setAddressLine2(addressLine2.isEmpty() ? null : addressLine2);
114	            request.setAddress(addressLine2.isEmpty() ? addressLine1 : addressLine1 + " " + addressLine2);
115	        }
116	        else {
117	            request.setAddress(OwnerAddress.normalize(request.getAddress()));
118	        }
119	        List<String> missing = new ArrayList<>();
120	        if (isBlank(request.getFirstName())) {
121	            missing.add("firstName");
122	        }
123	        if (isBlank(request.getLastName())) {
124	            missing.add("lastName");
125	        }
126	        if (isBlank(request.getAddress())) {
127	            missing.add("address");
128	        }
129	        if (isBlank(request.getCity())) {
130	            missing.add("city");
131	        }
132	        if (isBlank(request.getTelephone())) {
133	            missing.add("telephone");
134	        }
135	        if (!missing.isEmpty()) {
136	            throw new MissingOwnerFieldsException(missing);
137	        }
138	        request.setTelephone(TelephoneE164.normalize(request.getTelephone()));
139	        request.setEmail(OwnerEmail.normalize(request.getEmail()));
140	        // Postcode is optional; when present it must be a 4-digit code valid for the city's region.
141	        Postcode.validate(request.getPostcode(), request.getCity());
142	        // Registration date is optional; when supplied it may be back-dated but never into the future.
143	        LocalDate registrationDate = request.getRegistrationDate();
144	        if (registrationDate != null && registrationDate.isAfter(LocalDate.now())) {
145	            throw new FutureRegistrationDateException(registrationDate);
146	        }
147	        validated.set(request);
148	    }
149	
150	    private static boolean isBlank(String value) {
151	        return value == null || value.isBlank();
152	    }
153	}
