155	package org.springframework.samples.petclinic.rest.function.owner;
156	
157	import net.officefloor.plugin.variable.Val;
158	import org.springframework.samples.petclinic.model.Owner;
159	import org.springframework.samples.petclinic.repository.OwnerRepository;
160	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
161	import org.springframework.samples.petclinic.rest.escalation.DuplicateOwnerIdentityException;
162	
163	/**
164	 * The duplicate-detection step of {@code POST /api/owners}. Duplicate detection is the single
165	 * {@code identityKey} (see {@link OwnerIdentityKey}): a request is a duplicate only when an existing
166	 * owner carries the <em>same whole key</em> — normalized telephone, email and {@code soundex(lastName)}
167	 * all equal. There is no separate household-duplicate block: the postcode is not part of the key, so
168	 * two owners with the same last name and postcode but different telephones have different keys and are
169	 * both allowed (the weaker overlap is a soft match, see {@link AssignPossibleDuplicate}); only a
170	 * genuine re-submission of the same owner is rejected with 409.
171	 *
172	 * <p>The email-domain blocklist is applied earlier, in {@link ValidateNewOwner}, so a disposable
173	 * domain is a 400 before this step runs. Soft-deleted owners are ignored here.
174	 *
175	 * <p>The {@code sharesHousehold} hint bypasses this block: a request that declares itself a member
176	 * of a shared household is allowed through and created as a legitimate second member (and is not
177	 * flagged as a possible duplicate, see {@link AssignPossibleDuplicate}).
178	 *
179	 * <p>Runs after {@link ValidateNewOwner} has normalized the request and before {@link BuildOwner},
180	 * so a duplicate is a 409 rather than a persisted record.
181	 */
182	public class CheckOwnerIdentityUnique {
183	
184	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
185	            throws DuplicateOwnerIdentityException {
186	        if (Household.sharesHousehold(request)) {
187	            return; // declared household member: bypass the duplicate block
188	        }
189	        String identityKey = OwnerIdentityKey.forRequest(request);
190	        for (Owner owner : ownerRepository.findAll()) {
191	            if (owner.isDeleted()) {
192	                continue; // a soft-deleted owner no longer blocks a new create
193	            }
194	            if (identityKey.equals(OwnerIdentityKey.forOwner(owner))) {
195	                throw new DuplicateOwnerIdentityException(Household.idFor(request));
196	            }
197	        }
198	    }
199	}
