233	package org.springframework.samples.petclinic.rest.function.owner;
234	
235	import java.time.LocalDate;
236	
237	import net.officefloor.plugin.variable.Val;
238	import org.springframework.samples.petclinic.repository.OwnerRepository;
239	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
240	import org.springframework.samples.petclinic.rest.escalation.DailyOwnerLimitException;
241	
242	/**
243	 * Rejects a create-owner request once a business day's creation quota is exhausted: if 100 or more
244	 * owners already carry the {@code registrationDate} this owner would receive, no further owner may
245	 * be created for that day. The counted day is the effective registration date (supplied on the
246	 * request or defaulted to the server date) rolled forward onto a business day, matching how
247	 * {@link BuildOwner} stamps the new owner via {@link BusinessDay#rollForward(LocalDate)}, so the
248	 * owners this rule counts are exactly those sharing the resulting day. Runs after
249	 * {@link ValidateNewOwner} has published the request, and before {@link BuildOwner}, so a full day
250	 * is a 429 rather than a persisted record.
251	 */
252	public class CheckOwnerDailyLimit {
253	
254	    /** Maximum number of owners that may be created in a single day. */
255	    private static final long DAILY_LIMIT = 100;
256	
257	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
258	            throws DailyOwnerLimitException {
259	        LocalDate effective = request.getRegistrationDate();
260	        if (effective == null) {
261	            effective = LocalDate.now();
262	        }
263	        // Count owners against the same adjusted business day BuildOwner will stamp on this owner,
264	        // so a weekend create is bucketed with the Monday it rolls forward to.
265	        LocalDate businessDay = BusinessDay.rollForward(effective);
266	        long createdThatDay = ownerRepository.findAll().stream()
267	                .filter(existing -> businessDay.equals(existing.getRegistrationDate()))
268	                .count();
269	        if (createdThatDay >= DAILY_LIMIT) {
270	            throw new DailyOwnerLimitException(createdThatDay);
271	        }
272	    }
273	}
