300	package org.springframework.samples.petclinic.rest.function.owner;
301	
302	import java.util.HashSet;
303	import java.util.Set;
304	
305	import net.officefloor.plugin.variable.Val;
306	import org.springframework.samples.petclinic.model.Owner;
307	import org.springframework.samples.petclinic.repository.OwnerRepository;
308	import org.springframework.samples.petclinic.util.CheckDigit;
309	import org.springframework.samples.petclinic.util.FiscalYear;
310	import org.springframework.samples.petclinic.util.IdentityVersion;
311	import org.springframework.samples.petclinic.util.LocalityResolver;
312	import org.springframework.samples.petclinic.util.Sha256Hash;
313	
314	/**
315	 * Assigns the owner's {@code memberId} before it is saved. It unifies the former
316	 * {@code customerCode} and {@code membershipNumber} into a single value formatted
317	 * {@code <REGION><FY><HASH8><CHK>}, where:
318	 *
319	 * <ul>
320	 * <li>{@code REGION} is the version-2 region code: the region derived from the postcode (see
321	 * {@link LocalityResolver}) with the fixed {@link IdentityVersion#TAG} mixed in, so it never equals
322	 * a version-1 region and the plain {@code locality} is no longer read back off it;</li>
323	 * <li>{@code FY} is the last two digits of the fiscal year (starting 1 July) of the
324	 * business-day-adjusted {@code registrationDate}, zero-padded;</li>
325	 * <li>{@code HASH8} is the first 8 upper-case hex characters of SHA-256 over the concatenation of
326	 * the normalized telephone and the last name (the same HASH8 used by the region-and-hash identity);
327	 * and</li>
328	 * <li>{@code CHK} is a single Luhn check digit computed over the digits of
329	 * {@code <REGION><FY><HASH8>} (see {@link CheckDigit}).</li>
330	 * </ul>
331	 *
332	 * (e.g. {@code NSW273F1A9C2B4}.) The telephone was normalized to E.164 by {@link ValidateNewOwner},
333	 * so {@code owner.getTelephone()} is already the normalized value, and {@link BuildOwner} has set the
334	 * business-day-adjusted {@code registrationDate}.
335	 *
336	 * <p>Should the computed id collide with an existing owner's {@code memberId}, it is de-duplicated by
337	 * appending {@code -<n>} with the smallest {@code n} of 2 or more that makes it unique
338	 * (e.g. {@code NSW273F1A9C2B4-2}). Runs after {@link BuildOwner} and before {@link SaveOwner}, so
339	 * {@link OwnerRepository#findAll()} returns only the pre-existing owners. Mutates the entity in place
340	 * so {@link SaveOwner} persists it.
341	 */
342	public class AssignMemberId {
343	
344	    /** Number of upper-case hex characters taken from the SHA-256 digest. */
345	    private static final int HASH_LENGTH = 8;
346	
347	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
348	        String region = LocalityResolver.localityOf(owner.getPostcode(), owner.getCity())
349	                + IdentityVersion.TAG;
350	        String fy = String.format("%02d", FiscalYear.yearOf(owner.getRegistrationDate()) % 100);
351	        String hash8 = Sha256Hash.upperHex(owner.getTelephone() + owner.getLastName(), HASH_LENGTH);
352	        String body = region + fy + hash8;
353	        String baseId = body + CheckDigit.luhnOf(body);
354	
355	        Set<String> existingIds = new HashSet<>();
356	        for (Owner other : ownerRepository.findAll()) {
357	            existingIds.add(other.getMemberId());
358	        }
359	
360	        String memberId = baseId;
361	        for (int n = 2; existingIds.contains(memberId); n++) {
362	            memberId = baseId + "-" + n;
363	        }
364	        owner.setMemberId(memberId);
365	    }
366	}
