407	        String firstName = owner.getFirstName();
408	        String lastName = owner.getLastName();
409	        int count = 0;
410	        for (Owner other : ownerRepository.findAll()) {
411	            if (equalsIgnoreCase(firstName, other.getFirstName())
412	                    && equalsIgnoreCase(lastName, other.getLastName())) {
413	                count++;
414	            }
415	        }
416	        owner.setNamesakeCount(count);
417	    }
418	
419	    private static boolean equalsIgnoreCase(String a, String b) {
420	        return (a == null) ? (b == null) : a.equalsIgnoreCase(b);
421	    }
422	}
