424	package org.springframework.samples.petclinic.rest.function.owner;
425	
426	import net.officefloor.plugin.variable.Val;
427	import org.springframework.samples.petclinic.model.Owner;
428	import org.springframework.samples.petclinic.repository.OwnerRepository;
429	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
430	
431	/**
432	 * Assigns the owner's soft-match flags {@code possibleDuplicate} / {@code possibleDuplicateOf}. An
433	 * exact-identity duplicate has already been rejected with 409 by {@link CheckOwnerIdentityUnique}, so
434	 * every owner reaching this step is being created. This step flags the weaker overlap: an owner that
435	 * shares an existing owner's {@link Soundex Soundex code} of the last name and its {@code postcode}
436	 * but carries a <em>different</em> {@code identityKey} (see {@link OwnerIdentityKey}). Because the
437	 * telephone (and email) are part of that key, two owners with the same last name and postcode but a
438	 * different telephone differ in their key and so are flagged here rather than rejected. When such a
439	 * match exists {@code possibleDuplicate} is set true and {@code possibleDuplicateOf} to the matching
440	 * owner's id (the lowest id when several match, for determinism); otherwise {@code possibleDuplicate}
441	 * is false and {@code possibleDuplicateOf} left absent.
442	 *
443	 * <p>A declared household member (a request with {@code sharesHousehold} true) is <em>not</em> a
444	 * suspected duplicate: it has explicitly declared it shares the household, so its flags are left
445	 * unset.
446	 *
447	 * <p>Runs after {@link BuildOwner} has produced the {@link Owner} and before {@link SaveOwner}
448	 * persists it, so {@link OwnerRepository#findAll()} returns only the pre-existing owners and the new
449	 * owner never matches itself. Mutates the entity in place so {@link SaveOwner} stores the values and
450	 * later reads return them.
451	 */
452	public class AssignPossibleDuplicate {
453	
454	    public void service(@Val OwnerFieldsDto request, @Val Owner owner, OwnerRepository ownerRepository) {
455	        if (Household.sharesHousehold(request)) {
456	            // A declared household member is not a suspected duplicate.
457	            owner.setPossibleDuplicate(false);
458	            owner.setPossibleDuplicateOf(null);
459	            return;
460	        }
461	        String postcode = owner.getPostcode();
462	        Integer matchId = null;
463	        if (postcode != null && !postcode.isBlank()) {
464	            String soundex = Soundex.soundex(owner.getLastName());
465	            String identityKey = OwnerIdentityKey.forOwner(owner);
466	            for (Owner other : ownerRepository.findAll()) {
467	                if (other.isDeleted()) {
468	                    continue; // a soft-deleted owner is not a possible-duplicate match
469	                }
470	                if (soundex.equals(Soundex.soundex(other.getLastName()))
471	                        && postcode.equals(other.getPostcode())
472	                        && !identityKey.equals(OwnerIdentityKey.forOwner(other))) {
473	                    if (matchId == null || (other.getId() != null && other.getId() < matchId)) {
474	                        matchId = other.getId();
475	                    }
476	                }
477	            }
478	        }
479	        owner.setPossibleDuplicate(matchId != null);
480	        owner.setPossibleDuplicateOf(matchId);
481	    }
482	}
